try {
  throw new Error('Absichtlicher Testfehler');
  const response = $input.first().json;

  // Prüfen, ob Fahrzeugdaten vorhanden sind
  if (!Array.isArray(response.Results) || !response.Results[0]) {
    throw new Error(
      'Die API-Antwort enthält keine Fahrzeugdaten unter Results[0].'
    );
  }

  const r = response.Results[0];
  const text = value => String(value ?? '').trim();
  const year = text(r.ModelYear);

  // Erfolgreiche Verarbeitung
  return [{
    json: {
      status: 'erfolg',
      marke: text(r.Make) || 'unbekannt',
      modell: text(r.Model) || 'unbekannt',
      modelljahr: /^\d{4}$/.test(year) ? Number(year) : null,
      api_fehlercode: text(r.ErrorCode),
      api_hinweis: text(r.ErrorText),
      quelle: 'NHTSA vPIC',
      test_hinweis:
        'Öffentliche Teil-FIN; keine vollständige Fahrzeugidentifikation.'
    }
  }];

} catch (error) {
  // Fallback: verständliche Ausgabe statt Abbruch
  return [{
    json: {
      status: 'fehler',
      marke: 'unbekannt',
      modell: 'unbekannt',
      modelljahr: null,
      api_fehlercode: '',
      api_hinweis: '',
      quelle: 'NHTSA vPIC',
      test_hinweis:
        'Fahrzeugdaten konnten nicht verarbeitet werden. Bitte Eingabe prüfen oder später erneut versuchen.',
      fehlermeldung: error.message
    }
  }];
}

const daten = $input.first().json;

// Prüfen, ob die FIN fehlt oder nur Leerzeichen enthält
const vin = String(daten.vin ?? '').trim();

if (vin === '') {
  throw new Error(
    'Bitte das Pflichtfeld „vin“ (Fahrzeugidentifikationsnummer) ausfüllen.'
  );
}

// Mit gültiger Eingabe zum API-Aufruf weitergehen
return [{
  json: {
    ...daten,
    vin
  }
}];
